import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UsersService } from '../users/users.service';
import { AUTH_TOKEN_TYPE, AuthTokenPayload } from './auth-token.constants';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly usersService: UsersService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: process.env.JWT_SECRET ?? 'change-me-in-env',
    });
  }

  async validate(payload: AuthTokenPayload) {
    if (payload.tokenType !== AUTH_TOKEN_TYPE.ACCESS || typeof payload.sub !== 'string' || !payload.sub) {
      throw new UnauthorizedException('Invalid access token');
    }

    // Resolve current permissions and reject tokens belonging to deleted accounts.
    const user = await this.usersService.findById(payload.sub);

    if (!user) {
      throw new UnauthorizedException('Invalid access token');
    }

    return {
      id: user.id,
      email: user.email,
      role: user.role,
    };
  }
}

