        role: registerDto.role,
      });
      const user = await this.usersService.getById(existingUser.id);
      return this.createEmailVerificationResponse(user);
    }

    const user = await this.usersService.create({
      email: registerDto.email,
      password: hashedPassword,
      role: registerDto.role,
    });
    await this.issueEmailVerificationOtp(user);

    return this.createEmailVerificationResponse(user);
  }

  async login(loginDto: LoginDto) {
    const user = await this.usersService.findByEmailWithPassword(loginDto.email);
    if (!user || !user.password) {
      throw new UnauthorizedException('Invalid email or password');
    }

    const passwordMatches = await bcrypt.compare(loginDto.password, user.password);

    if (!passwordMatches) {
      throw new UnauthorizedException('Invalid email or password');
    }

    if (!user.emailVerified) {
      await this.issueEmailVerificationOtp(user);
      return this.createEmailVerificationResponse(user);
    }

    return this.createAuthenticatedResponse(user);
  }

  async loginWithGoogle(credential: string, role?: SignupRole) {
    const user = await this.googleOAuthService.authenticate(credential, role);

    return this.createAuthenticatedResponse(user);
  }

