    const user = await this.usersService.findById(userId);

    if (!user) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (user.emailVerified) {
      throw new BadRequestException('Email is already verified');
    }

    const otpRecord = await this.emailOtpRepository.findLatestActiveByUserId(user.id);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      await this.emailOtpRepository.recordFailedAttempt(otpRecord.id, user.id, otpMaxAttempts());

      throw new BadRequestException('Invalid or expired verification code');
    }

    const completed = await this.emailOtpRepository.complete(otpRecord.id, user.id, otpMaxAttempts());
    if (!completed) throw new BadRequestException('Invalid or expired verification code');
