export const REDACTED = '[REDACTED]';

/** Keys (matched case-insensitively) whose values must never reach the logs. */
const SENSITIVE_KEYS = new Set([
  'password',
  'newpassword',
  'currentpassword',
  'confirmpassword',
  'otp',
  'code',
  'secret',
  'token',
  'accesstoken',
  'refreshtoken',
  'otptoken',
  'idtoken',
  'ticket',
  'authorization',
  'cookie',
  'set-cookie',
]);

/**
 * Deep-copies JSON-like data with sensitive values replaced so request and
 * response bodies can be logged without leaking credentials. Only plain objects
 * and arrays are walked; dates, Prisma decimals and primitives pass through and
 * are left for JSON.stringify to serialize.
 */
export function redactSensitive(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => redactSensitive(item));
  }

  if (!isPlainObject(value)) {
    return value;
  }

  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [
      key,
      SENSITIVE_KEYS.has(key.toLowerCase()) ? REDACTED : redactSensitive(entry),
    ]),
  );
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const prototype: unknown = Object.getPrototypeOf(value);

  return prototype === Object.prototype || prototype === null;
}

