 * (or the client went away): method, path, status, duration, request id, the
 * caller and, unless disabled, the redacted request and response bodies.
 *
 * It runs before the guards, so requests rejected with 401/403 and unknown
 * routes are logged as well. Bodies are captured by wrapping `res.json`, which
 * is how every API envelope (success and error) is written.
 *
 * Body logging follows LOG_HTTP_BODIES when set and is otherwise on everywhere
 * except production.
 */
@Injectable()
export class RequestLoggerMiddleware implements NestMiddleware {
  private readonly logger = new Logger('HTTP');
  private readonly logBodies = shouldLogBodies();

  use(request: Request, response: Response, next: NextFunction): void {
    const startedAt = process.hrtime.bigint();
    const requestId = getRequestId(request);
    let responseBody: unknown;
    let logged = false;

    response.setHeader('X-Request-Id', requestId);

    if (this.logBodies) {
      const json = response.json;

      response.json = (body?: unknown) => {
        responseBody = body;

        return Reflect.apply(json, response, [body]);
      };
    }

    const finalize = (aborted: boolean): void => {
      if (logged) {
        return;
      }

      logged = true;

      const durationMs = (Number(process.hrtime.bigint() - startedAt) / 1e6).toFixed(1);
      const user = (request as AuthenticatedRequest).user;
      const status = aborted ? 'aborted' : String(response.statusCode);
      const path = request.originalUrl || request.url;
      let line = `${request.method} ${path} ${status} ${durationMs}ms requestId=${requestId} user=${user?.id ?? '-'} ip=${request.ip ?? '-'}`;

      if (this.logBodies) {
        line += ` request=${this.serialize(request.body)} response=${this.serialize(responseBody)}`;
      }

      if (response.statusCode >= 500) {
        this.logger.error(line);
      } else if (aborted || response.statusCode >= 400) {
        this.logger.warn(line);
      } else {
        this.logger.log(line);
      }
    };

    response.once('finish', () => finalize(false));
    response.once('close', () => finalize(!response.writableFinished));

    next();
  }

  private serialize(body: unknown): string {
    if (body === undefined) {
      return '-';
    }

    try {
      const text = JSON.stringify(redactSensitive(body));

      return text.length > MAX_BODY_LENGTH
