import { STATUS_CODES } from 'node:http';
import {
  ArgumentsHost,
  BadRequestException,
  Catch,
  ConflictException,
  ExceptionFilter,
  HttpException,
  InternalServerErrorException,
  Logger,
  NotFoundException,
  ServiceUnavailableException,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { Request, Response } from 'express';
import { PRISMA_ERROR_CODE } from '../constants/prisma-error.constants';
import { createResponseMetadata, ResponseMetadata } from '../http/response-metadata';
import { redactUrl } from '../logging/redact-url';

type ExceptionFactory = () => HttpException;
type ErrorMessage = string | string[];

interface ApiErrorResponse {
  success: false;
  statusCode: number;
  message: ErrorMessage;
  error: string;
  data: null;
  meta: ResponseMetadata;
  code?: string;
}

/**
 * Gives every API failure one stable envelope while translating known Prisma
 * failures into safe HTTP errors and hiding unexpected internal details.
 */
@Catch()
export class ApiExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(ApiExceptionFilter.name);

  private readonly prismaHandlers: Record<string, ExceptionFactory | undefined> = {
    [PRISMA_ERROR_CODE.UNIQUE_CONSTRAINT]: () => new ConflictException('Resource already exists'),
    [PRISMA_ERROR_CODE.REQUIRED_RELATION_VIOLATION]: () => new ConflictException('Resource already exists'),
    [PRISMA_ERROR_CODE.WRITE_CONFLICT]: () =>
      new ConflictException('The request conflicted with another operation, please retry'),

    [PRISMA_ERROR_CODE.RECORD_NOT_FOUND]: () => new NotFoundException('Resource not found'),
    [PRISMA_ERROR_CODE.WHERE_RECORD_NOT_FOUND]: () => new NotFoundException('Resource not found'),
    [PRISMA_ERROR_CODE.RELATED_RECORD_NOT_FOUND]: () => new NotFoundException('A related resource was not found'),
    [PRISMA_ERROR_CODE.REQUIRED_CONNECTED_RECORDS_NOT_FOUND]: () =>
      new NotFoundException('A related resource was not found'),

    [PRISMA_ERROR_CODE.FOREIGN_KEY_CONSTRAINT]: () => new BadRequestException('A referenced resource does not exist'),
    [PRISMA_ERROR_CODE.VALUE_TOO_LONG]: () => new BadRequestException('A provided value is too long'),
    [PRISMA_ERROR_CODE.VALUE_OUT_OF_RANGE]: () => new BadRequestException('A provided value is out of range'),
    [PRISMA_ERROR_CODE.NULL_CONSTRAINT]: () => new BadRequestException('A required value is missing'),
    [PRISMA_ERROR_CODE.MISSING_REQUIRED_VALUE]: () => new BadRequestException('A required value is missing'),

    [PRISMA_ERROR_CODE.CONNECTION_POOL_TIMEOUT]: () =>
      new ServiceUnavailableException('The service is busy, please retry shortly'),
  };

  catch(exception: unknown, host: ArgumentsHost): void {
    const http = host.switchToHttp();
    const request = http.getRequest<Request>();
    const response = http.getResponse<Response>();
    const httpException = this.toHttpException(exception, request);
    const statusCode = httpException.getStatus();
    const meta = createResponseMetadata(request);

    if (statusCode >= 500 && !(exception instanceof Prisma.PrismaClientKnownRequestError)) {
      const stack = exception instanceof Error ? exception.stack : undefined;
      this.logger.error(`${request.method} ${redactUrl(request.url)}: unhandled exception`, stack);
    }

    response.setHeader('X-Request-Id', meta.requestId);
    response.status(statusCode).json(this.toErrorResponse(httpException, meta));
  }

  private toHttpException(exception: unknown, request: Request): HttpException {
    if (exception instanceof HttpException) {
      return exception;
    }

    if (exception instanceof Prisma.PrismaClientKnownRequestError) {
      const factory = this.prismaHandlers[exception.code];
      const context = `${request.method} ${redactUrl(request.url)} — Prisma ${exception.code}`;

      if (factory) {
        this.logger.warn(`${context}: ${exception.message.replace(/\s+/g, ' ').trim()}`);
        return factory();
      }

      this.logger.error(`${context}: unmapped Prisma error code`, exception.stack);
    }

    return new InternalServerErrorException();
  }

  private toErrorResponse(exception: HttpException, meta: ResponseMetadata): ApiErrorResponse {
    const statusCode = exception.getStatus();
    const rawResponse = exception.getResponse();
    const responseBody =
      typeof rawResponse === 'object' && rawResponse !== null ? (rawResponse as Record<string, unknown>) : undefined;
    const rawMessage = responseBody?.message ?? rawResponse;
    const message = this.isErrorMessage(rawMessage) ? rawMessage : exception.message;
    const error = typeof responseBody?.error === 'string' ? responseBody.error : (STATUS_CODES[statusCode] ?? 'Error');
    const code = typeof responseBody?.code === 'string' ? responseBody.code : undefined;

    return {
      success: false,
      statusCode,
      message,
      error,
      data: null,
      meta,
      ...(code ? { code } : {}),
    };
  }

  private isErrorMessage(value: unknown): value is ErrorMessage {
    return typeof value === 'string' || (Array.isArray(value) && value.every((item) => typeof item === 'string'));
  }
}

