import { randomUUID } from 'node:crypto';
import { Request } from 'express';

const REQUEST_ID_PATTERN = /^[A-Za-z0-9._:-]{1,128}$/;

type RequestWithId = Request & { requestId?: string };

export interface ResponseMetadata {
  requestId: string;
  timestamp: string;
  path: string;
  method: string;
}

/**
 * The request's correlation id: a well-formed incoming X-Request-Id header is
 * honoured, otherwise one is minted. It is cached on the request so the access
 * log, the response envelope and the error envelope all report the same id.
 */
export function getRequestId(request: Request): string {
  const requestWithId = request as RequestWithId;

  if (requestWithId.requestId) {
    return requestWithId.requestId;
  }

  const headerValue = request.headers['x-request-id'];
  const incomingRequestId = Array.isArray(headerValue) ? headerValue[0] : headerValue;
  const requestId = incomingRequestId && REQUEST_ID_PATTERN.test(incomingRequestId) ? incomingRequestId : randomUUID();

  requestWithId.requestId = requestId;

  return requestId;
}

export function createResponseMetadata(request: Request): ResponseMetadata {
  return {
    requestId: getRequestId(request),
    timestamp: new Date().toISOString(),
    path: request.originalUrl || request.url,
    method: request.method.toUpperCase(),
  };
}

